function luminance(hex: string): number {
    const n = parseInt(hex.slice(1), 16);
    const lin = (v: number) => {
        const c = v / 255;
        return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * lin((n >> 16) & 255) + 0.7152 * lin((n >> 8) & 255) + 0.0722 * lin(n & 255);
}

/** Sotto questa luminanza il colore di marca sparisce su uno sfondo scuro. */
const DARK_BRAND_LUMINANCE = 0.08;

/** Il colore di marca è quasi nero (Next.js, Vercel, GitHub…)? */
export function isDarkBrand(id: SkillNames): boolean {
    return luminance(BRAND_COLORS[id]) < DARK_BRAND_LUMINANCE;
}

/** Colore di marca leggibile sul tema: i marchi neri diventano chiari sul tema scuro. */
export function readableBrandColor(id: SkillNames, theme: "dark" | "light"): string {
    return theme === "dark" && isDarkBrand(id) ? "#F4F4F5" : BRAND_COLORS[id];
}

/** Margine lasciato attorno al logo, in frazione del lato (per parte). */
const MARGIN = 0.12;

const boxCache = new Map<string, number[]>();
const pathCache = new Map<string, Path2D[]>();

function parseBox(viewBox: string): number[] {
    let box = boxCache.get(viewBox);
    if (!box) {
        box = viewBox.trim().split(/[\s,]+/).map(Number);
        boxCache.set(viewBox, box);
    }
    return box;
}

function parsePaths(id: SkillNames, paths: IconPath[]): Path2D[] {
    let parsed = pathCache.get(id);
    if (!parsed) {
        parsed = paths.map((p) => new Path2D(p.d));
        pathCache.set(id, parsed);
    }
    return parsed;
}

const TEXT_FONT =
    '700 100px ui-sans-serif, system-ui, -apple-system, "Segoe UI", Inter, Roboto, Helvetica, Arial, sans-serif';

/** Disegna l'icona centrata in un quadrato (x,y,size) su un canvas 2D. `color` = colore unico (loghi monocromi). */
export function drawKeyIcon(
    ctx: CanvasRenderingContext2D,
    id: SkillNames,
    x: number,
    y: number,
    size: number,
    color: string,
): void {
    const spec = KEY_ICONS[id];
    const avail = size * (1 - 2 * MARGIN);
    const cx = x + size / 2;
    const cy = y + size / 2;

    ctx.save();
    ctx.fillStyle = color;

    if (spec.kind === "paths") {
        const [minX, minY, w, h] = parseBox(spec.viewBox);
        const s = Math.min(avail / w, avail / h);
        ctx.translate(cx - (minX + w / 2) * s, cy - (minY + h / 2) * s);
        ctx.scale(s, s);

        const parsed = parsePaths(id, spec.paths);
        const baseAlpha = ctx.globalAlpha;
        spec.paths.forEach((p, i) => {
            ctx.globalAlpha = baseAlpha * (p.opacity ?? 1);
            ctx.fill(parsed[i], p.fillRule ?? "nonzero");
        });
    } else {
        // Si misura a 100px e si scala per farla entrare nel quadrato
        ctx.font = TEXT_FONT;
        ctx.textAlign = "left";
        ctx.textBaseline = "alphabetic";
        const m = ctx.measureText(spec.text);
        const inkW = m.actualBoundingBoxLeft + m.actualBoundingBoxRight;
        const inkH = m.actualBoundingBoxAscent + m.actualBoundingBoxDescent;
        const s = Math.min(avail / inkW, avail / inkH) * (spec.scale ?? 1);
        ctx.translate(cx, cy);
        ctx.scale(s, s);
        ctx.fillText(
            spec.text,
            -(m.actualBoundingBoxRight - m.actualBoundingBoxLeft) / 2,
            (m.actualBoundingBoxAscent - m.actualBoundingBoxDescent) / 2,
        );
    }
    ctx.restore();
}
